import json, math, re, io, contextlib
src = open('/var/tmp/foundry-work/analysis/analyze.py').read()
src = src.split("by = {}")[0]  # keep only function defs + data load
ns = {}
exec(src, ns)
rows = ns['rows']
def run(excl_extra=()):
    kept = [r for r in rows if not r['excl'] and r['id'] not in excl_extra]
    by = {}
    for r in kept: by.setdefault(r['cond'], []).append((r['S'], abs(r['v'])))
    out = {}
    for c in ['C1','C6']:
        out[c] = ns['fit_mm'](by[c])[:2]
    vm1 = out['C1'][0]; vm6 = out['C6'][0]
    res = {}
    for c in ['C1','C6']: res[c] = out[c]
    res['C2'] = ns['fit_mm'](by['C2'], vmax_fixed=vm1)[:2]
    res['C7'] = ns['fit_mm'](by['C7'], vmax_fixed=vm1)[:2]
    res['C4'] = ns['fit_mm'](by['C4'], vmax_fixed=vm6)[:2]
    return res
base = run()
alt = run(('QD-0649',))
alt2 = run(('QD-0649','QD-0314'))
for c in base:
    print(c, 'base Vmax=%.4f Km=%.2f' % base[c], '| excl0649 Vmax=%.4f Km=%.2f' % alt[c], '| excl0649+0314 Vmax=%.4f Km=%.2f' % alt2[c])

